// JLPT past papers: data model and pure logic (no React). The exam content itself is NOT part of the
// repository: it is generated by scripts/jlpt/n2build.py into public/jlpt/<level>/ (gitignored) and
// fetched at runtime. See docs/JLPT-PAST-PAPERS.md.

export type PastSection = 'goi' | 'bun' | 'dok' | 'cho';
export type PastType =
  | 'yomi' | 'hyouki' | 'gokeisei' | 'bunmyaku' | 'iikae' | 'youhou'
  | 'keishiki' | 'narabe' | 'bunshou'
  | 'tanbun' | 'chuubun' | 'tougou' | 'shuchou' | 'jouhou'
  | 'kadai' | 'point' | 'gaiyou' | 'sokuji' | 'ltougou';

export const PAST_SECTIONS: PastSection[] = ['goi', 'bun', 'dok', 'cho'];
export const PAST_SECTION_JP: Record<PastSection, string> = { goi: '文字・語彙', bun: '文法', dok: '読解', cho: '聴解' };
/** Suggested minutes per part (N2). */
export const PAST_MINUTES: Record<PastSection | 'all', number> = { goi: 20, bun: 25, dok: 60, cho: 50, all: 155 };

export const PAST_TYPES: { type: PastType; sec: PastSection; jp: string }[] = [
  { type: 'yomi', sec: 'goi', jp: '漢字読み' }, { type: 'hyouki', sec: 'goi', jp: '表記' }, { type: 'gokeisei', sec: 'goi', jp: '語形成' },
  { type: 'bunmyaku', sec: 'goi', jp: '文脈規定' }, { type: 'iikae', sec: 'goi', jp: '言い換え類義' }, { type: 'youhou', sec: 'goi', jp: '用法' },
  { type: 'keishiki', sec: 'bun', jp: '文法形式の判断' }, { type: 'narabe', sec: 'bun', jp: '文の組み立て' }, { type: 'bunshou', sec: 'bun', jp: '文章の文法' },
  { type: 'tanbun', sec: 'dok', jp: '内容理解（短文）' }, { type: 'chuubun', sec: 'dok', jp: '内容理解（中文）' }, { type: 'tougou', sec: 'dok', jp: '統合理解' },
  { type: 'shuchou', sec: 'dok', jp: '主張理解（長文）' }, { type: 'jouhou', sec: 'dok', jp: '情報検索' },
  { type: 'kadai', sec: 'cho', jp: '課題理解' }, { type: 'point', sec: 'cho', jp: 'ポイント理解' }, { type: 'gaiyou', sec: 'cho', jp: '概要理解' },
  { type: 'sokuji', sec: 'cho', jp: '即時応答' }, { type: 'ltougou', sec: 'cho', jp: '統合理解' },
];
export const typeMeta = (t: PastType) => PAST_TYPES.find(x => x.type === t)!;
const TYPE_ORDER = new Map(PAST_TYPES.map((t, i) => [t.type, i]));
const LISTEN_TYPE: Record<number, PastType> = { 1: 'kadai', 2: 'point', 3: 'gaiyou', 4: 'sokuji', 5: 'ltougou' };
export const LISTEN_INSTR: Record<number, string> = {
  1: 'まず質問を聞いてください。それから話を聞いて、問題用紙の1から4の中から、最もよいものを一つ選んでください。',
  2: 'まず質問を聞いてください。そのあと、問題用紙のせんたくしを読んでください。それから話を聞いて、1から4の中から、最もよいものを一つ選んでください。',
  3: '問題用紙に何もいんさつされていません。話を聞いて、質問とせんたくしを聞いて、1から4の中から、最もよいものを一つ選んでください。',
  4: '問題用紙に何もいんさつされていません。まず文を聞いてください。それから、それに対する返事を聞いて、1から3の中から、最もよいものを一つ選んでください。',
  5: '長めの話を聞きます。問題用紙にメモをとってもかまいません。',
};

// ---------- raw files (as written by n2build.py) ----------
export interface RawQuestion { n: number; q: string; o: string[]; a: number; g: number }
export interface RawMondai { no: number; sec: Exclude<PastSection, 'cho'>; type: PastType; instr: string; groups: string[]; qs: RawQuestion[]; img?: string[] }
export interface RawListen {
  q: string; qW: number; qH: number; crops: Record<string, number[][]>;
  sc: string; scW: number; scH: number;
  mondai: { no: number; ans: [string, number][] }[];
  chunks: { u: string; d: number }[]; dur: number | null;
}
export interface RawExam { tag: string; label: string; mondai: RawMondai[]; listen?: RawListen }

// ---------- in-memory bank ----------
export interface PastQuestion {
  id: string; level: string; tag: string; n: string; no: number; sec: PastSection; type: PastType;
  q: string; o: string[]; a: number; g: number; unit: string; mi: number;
}
export interface PastBank { level: string; tags: string[]; exams: Record<string, RawExam>; list: PastQuestion[]; byId: Record<string, PastQuestion> }

/** Make file paths inside an exam absolute (relative paths are relative to the level folder). */
export function resolveExam(raw: RawExam, levelBase: string): RawExam {
  const abs = (p: string) => (/^(\/|https?:)/.test(p) ? p : `${levelBase.replace(/\/$/, '')}/${p}`);
  const exam: RawExam = { ...raw, mondai: raw.mondai.map(m => (m.img ? { ...m, img: m.img.map(abs) } : m)) };
  if (raw.listen) exam.listen = { ...raw.listen, q: abs(raw.listen.q), sc: abs(raw.listen.sc), chunks: raw.listen.chunks.map(c => ({ ...c, u: abs(c.u) })) };
  return exam;
}

export function buildBank(level: string, exams: RawExam[]): PastBank {
  const sorted = [...exams].sort((a, b) => a.tag.localeCompare(b.tag));
  const bank: PastBank = { level, tags: sorted.map(e => e.tag), exams: {}, list: [], byId: {} };
  const L = level.toLowerCase();
  for (const ex of sorted) {
    bank.exams[ex.tag] = ex;
    ex.mondai.forEach((m, mi) => m.qs.forEach(q => {
      const id = `${L}-${ex.tag}-${q.n}`;
      const grouped = (m.sec === 'dok' || m.type === 'bunshou') && q.g >= 0;
      const e: PastQuestion = { id, level, tag: ex.tag, n: String(q.n), no: m.no, sec: m.sec, type: m.type, q: q.q, o: q.o, a: q.a, g: q.g, unit: grouped ? `${L}-${ex.tag}-${m.no}-${q.g}` : id, mi };
      bank.list.push(e); bank.byId[id] = e;
    }));
    // Listening is only offered when the exam has audio.
    if (ex.listen && ex.listen.chunks.length) ex.listen.mondai.forEach(m => m.ans.forEach(([lab, a]) => {
      const id = `${L}-${ex.tag}-L${m.no}-${lab}`; const [b, sub] = lab.split('-');
      const e: PastQuestion = { id, level, tag: ex.tag, n: lab, no: m.no, sec: 'cho', type: LISTEN_TYPE[m.no] ?? 'ltougou', q: `${b}番${sub ? ` · 質問${sub}` : ''}`, o: m.no === 4 ? ['1', '2', '3'] : ['1', '2', '3', '4'], a, g: -1, unit: id, mi: -1 };
      bank.list.push(e); bank.byId[id] = e;
    }));
  }
  return bank;
}

export const tagLabel = (tag: string) => { const [y, m] = tag.split('-'); return `${Number(m)}/${y}`; };
export function plain(html: string) { return String(html || '').replace(/<[^>]+>/g, '').replace(/&lt;/g, '<').replace(/&amp;/g, '&'); }
/** Exam markup -> HTML: [_] blank, [★] star blank, [48] boxed number. Input is sanitised by n2build.py (only u/p/br/b tags). */
export function examHtml(s: string) {
  return String(s || '')
    .replace(/\[_\]/g, '<span class="pp-slot"></span>')
    .replace(/\[★\]/g, '<span class="pp-slot pp-star">★</span>')
    .replace(/\[(\d+)\]/g, '<span class="pp-box">$1</span>');
}
export function instrOf(bank: PastBank, q: PastQuestion) { return q.sec === 'cho' ? LISTEN_INSTR[q.no] ?? '' : bank.exams[q.tag].mondai[q.mi].instr; }
export function passageOf(bank: PastBank, q: PastQuestion) { return q.sec !== 'cho' && q.g >= 0 ? bank.exams[q.tag].mondai[q.mi].groups[q.g] ?? '' : ''; }
export function imagesOf(bank: PastBank, q: PastQuestion) { return q.sec !== 'cho' ? bank.exams[q.tag].mondai[q.mi].img ?? [] : []; }

// ---------- progress ----------
/** [lastCorrect 0|1, attempts, wrongCount, timestamp] */
export type ProgressEntry = [number, number, number, number];
export function nextProgress(prev: ProgressEntry | undefined, ok: boolean, now = Date.now()): ProgressEntry {
  const p = prev ?? [0, 0, 0, 0];
  return [ok ? 1 : 0, p[1] + 1, p[2] + (ok ? 0 : 1), now];
}

// ---------- custom practice ----------
export type StatusFilter = 'all' | 'new' | 'wrong' | 'everwrong';
export interface CustomFilter { types: PastType[]; from: string; to: string; kw: string; status: StatusFilter; n: number | 'all'; order: 'random' | 'year'; mode: 'instant' | 'exam' }
export const DEFAULT_FILTER: CustomFilter = { types: ['yomi', 'hyouki'], from: '', to: '', kw: '', status: 'all', n: 20, order: 'random', mode: 'instant' };

export function filterPool(bank: PastBank, f: CustomFilter, prog: Record<string, ProgressEntry>) {
  const from = f.from || bank.tags[0] || ''; const to = f.to || bank.tags[bank.tags.length - 1] || '';
  let pool = bank.list.filter(q => f.types.includes(q.type) && q.tag >= from && q.tag <= to);
  if (f.status === 'new') pool = pool.filter(q => !prog[q.id]);
  if (f.status === 'wrong') pool = pool.filter(q => prog[q.id] && !prog[q.id][0]);
  if (f.status === 'everwrong') pool = pool.filter(q => prog[q.id] && prog[q.id][2] > 0);
  const terms = f.kw.trim().split(/[\s,、]+/).filter(Boolean);
  if (terms.length) pool = pool.filter(q => { const hay = plain(`${q.q} ${q.o.join(' ')} ${passageOf(bank, q)}`); return terms.every(t => hay.includes(t)); });
  return pool;
}

/** Pick questions unit by unit (a reading passage keeps all its questions) and order them for display. */
export function buildSessionIds(bank: PastBank, pool: PastQuestion[], n: number | 'all', order: 'random' | 'year', rand: () => number = Math.random) {
  const units = new Map<string, PastQuestion[]>();
  for (const q of pool) { const u = units.get(q.unit); if (u) u.push(q); else units.set(q.unit, [q]); }
  const keys = [...units.keys()];
  if (order === 'random') for (let i = keys.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [keys[i], keys[j]] = [keys[j], keys[i]]; }
  else keys.sort((a, b) => a.localeCompare(b, undefined, { numeric: true }));
  const ids: string[] = [];
  for (const k of keys) {
    if (n !== 'all' && ids.length >= n) break;
    const first = units.get(k)![0];
    const members = first.unit === first.id ? units.get(k)! : bank.list.filter(q => q.unit === k);
    members.forEach(q => ids.push(q.id));
  }
  return orderIds(bank, ids, order);
}
const SEC_ORDER: Record<PastSection, number> = { goi: 0, bun: 1, dok: 2, cho: 3 };
export function orderIds(bank: PastBank, ids: string[], order: 'random' | 'year') {
  const pos = new Map(ids.map((id, i) => [id, i]));
  const Q = bank.byId;
  return [...ids].sort((a, b) => {
    const x = Q[a], y = Q[b];
    if (order === 'year') return x.tag.localeCompare(y.tag) || SEC_ORDER[x.sec] - SEC_ORDER[y.sec] || x.no - y.no || pos.get(a)! - pos.get(b)!;
    return SEC_ORDER[x.sec] - SEC_ORDER[y.sec]
      || (x.sec === 'cho' ? x.tag.localeCompare(y.tag) || x.no - y.no : 0)
      || TYPE_ORDER.get(x.type)! - TYPE_ORDER.get(y.type)! || pos.get(a)! - pos.get(b)!;
  });
}
export function examIds(bank: PastBank, tag: string, part: PastSection | 'all') {
  return bank.list.filter(q => q.tag === tag && (part === 'all' || q.sec === part)).map(q => q.id);
}

export interface PastScore { correct: number; total: number; percent: number; byType: { type: PastType; correct: number; total: number }[] }
export function scoreSession(bank: PastBank, ids: string[], answers: Record<string, number>): PastScore {
  const by = new Map<PastType, { correct: number; total: number }>(); let correct = 0;
  for (const id of ids) {
    const q = bank.byId[id]; if (!q) continue;
    const t = by.get(q.type) ?? { correct: 0, total: 0 }; t.total++;
    if (answers[id] === q.a) { t.correct++; correct++; }
    by.set(q.type, t);
  }
  const byType = [...by.entries()].sort((a, b) => TYPE_ORDER.get(a[0])! - TYPE_ORDER.get(b[0])!).map(([type, v]) => ({ type, ...v }));
  return { correct, total: ids.length, percent: ids.length ? Math.round(correct / ids.length * 100) : 0, byType };
}

// ---------- tabs (one per mondai for a single exam, one per type for mixed sessions) ----------
export interface PastTab { key: string; sec: PastSection; label: string; ids: string[] }
export function tabsFor(bank: PastBank, ids: string[]): PastTab[] {
  const single = new Set(ids.map(id => bank.byId[id]?.tag)).size === 1;
  const tabs: PastTab[] = []; const idx = new Map<string, number>();
  for (const id of ids) {
    const q = bank.byId[id]; if (!q) continue;
    const key = single ? `${q.sec}-${q.no}` : `${q.sec}-${q.type}`;
    if (!idx.has(key)) { idx.set(key, tabs.length); tabs.push({ key, sec: q.sec, label: single ? `問題${q.no}` : typeMeta(q.type).jp, ids: [] }); }
    tabs[idx.get(key)!].ids.push(id);
  }
  return tabs;
}
export const tabKeyOf = (bank: PastBank, ids: string[], q: PastQuestion) =>
  new Set(ids.map(id => bank.byId[id]?.tag)).size === 1 ? `${q.sec}-${q.no}` : `${q.sec}-${q.type}`;

/** Locate a global time inside the chunked audio timeline. */
export function chunkAt(chunks: { d: number }[], t: number) {
  let s = 0;
  for (let i = 0; i < chunks.length; i++) { if (t < s + chunks[i].d || i === chunks.length - 1) return { index: i, offset: Math.max(0, t - s) }; s += chunks[i].d; }
  return { index: 0, offset: 0 };
}
